def fib(n):
    if n <= 1:
        return n
    dp = [0] * (n + 1)
    dp[0], dp[1] = 0, 1                   # base cases
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]     # recurrence as an assignment
    return dp[n]

